import React, { createContext, useState, useContext, ReactNode, useEffect } from 'react';

// Define types for our grievance system
export type GrievanceSeverity = 'Low' | 'Medium' | 'High' | 'Critical';
export type GrievanceMood = 'Annoyed' | 'Disappointed' | 'Frustrated' | 'Angry' | 'Furious';

export type Grievance = {
  id: string;
  title: string;
  description: string;
  mood: GrievanceMood;
  severity: GrievanceSeverity;
  date: string;
  createdAt: string;
  status: 'Pending' | 'Acknowledged' | 'Resolved';
};

type GrievanceContextType = {
  grievances: Grievance[];
  addGrievance: (grievance: Omit<Grievance, 'id' | 'createdAt' | 'status'>) => void;
  updateGrievanceStatus: (id: string, status: Grievance['status']) => void;
  getGrievance: (id: string) => Grievance | undefined;
};

// Create the context with a default value
const GrievanceContext = createContext<GrievanceContextType | undefined>(undefined);

// Create a provider component
export const GrievanceProvider: React.FC<{ children: ReactNode }> = ({ children }) => {
  const [grievances, setGrievances] = useState<Grievance[]>([]);

  // Load grievances from localStorage on initial render
  useEffect(() => {
    const savedGrievances = localStorage.getItem('grievances');
    if (savedGrievances) {
      setGrievances(JSON.parse(savedGrievances));
    }
  }, []);

  // Save grievances to localStorage whenever they change
  useEffect(() => {
    localStorage.setItem('grievances', JSON.stringify(grievances));
  }, [grievances]);

  const addGrievance = (grievance: Omit<Grievance, 'id' | 'createdAt' | 'status'>) => {
    const newGrievance: Grievance = {
      ...grievance,
      id: Date.now().toString(),
      createdAt: new Date().toISOString(),
      status: 'Pending',
    };

    setGrievances(prev => [newGrievance, ...prev]);
  };

  const updateGrievanceStatus = (id: string, status: Grievance['status']) => {
    setGrievances(prev => 
      prev.map(g => g.id === id ? { ...g, status } : g)
    );
  };

  const getGrievance = (id: string) => {
    return grievances.find(g => g.id === id);
  };

  return (
    <GrievanceContext.Provider value={{ grievances, addGrievance, updateGrievanceStatus, getGrievance }}>
      {children}
    </GrievanceContext.Provider>
  );
};

// Create a hook to use the grievance context
export const useGrievances = () => {
  const context = useContext(GrievanceContext);
  if (context === undefined) {
    throw new Error('useGrievances must be used within a GrievanceProvider');
  }
  return context;
};
